import json,numpy as np
from scipy.stats import rankdata
inp=json.load(open('inputs.json'));D=json.load(open('pronunciations.json'));ids=[x['id'] for x in inp['queries']]
choices=['coupler','guided','guided','shady','excite','coupler','cowbell','cases','excite','dismay','dismay','critic','shady','addition','supine','critic']
chosenp={w:D[w][0] for w in choices}; chosenp['supine']=['S','AH','P','AY','N']
A={k:v for k,v in np.load('final_full_dictionary_scores.npz').items()}; G={k:v for k,v in np.load('generative_scores.npz').items()}; known={x['word'] for x in inp['calibration']};valid=~np.isin(A['words'],list(known));raw=json.load(open('algorithm_only_outputs.json'));review=[]
for j,(qid,w) in enumerate(zip(ids,choices)):
 m=A['words']==w;best=A['scores'][m,j].min();r=int(1+(valid&(A['scores'][:,j]<best-1e-8)).sum());g=G['words']==w;gr=int(1+(G['scores'][:,j]<G['scores'][g,j].min()-1e-8).sum())
 review.append(dict(id=qid,word=w,phonemes=chosenp[w],ensemble_pronunciation_rank=r,gesture_model_pronunciation_rank=gr,algorithm_top1=raw['ensemble_candidates'][qid][0],confidence='low',human_inference=True))
notes={
 'coupler':'K-initial hypotheses with a medial labial and a final liquid/central vowel recur across models. Coupler is supported by both relative-position and shared-gesture models. The two relevant queries are unusually close neurally (2924 squared distance). Casbah, culpa, cowboy, and several names remain serious alternatives.',
 'guided':'The G/weak-onset, diphthong, and final voiced coronal hypotheses recur in both queries. Guided reconciles their rankings and is favored over proper-name aliases. Aided, outed, guider, and aside remain plausible; their query distance is 3299.',
 'shady':'The pair supports a fricative/affricate-like onset, front/diphthong vowel, coronal, and final high vowel. Shady is a lexical interpretation of this family. Cheetah, thirty, chitty, and other hypotheses remain plausible. Query distance 2959 supports, but does not prove, repetition.',
 'excite':'A weak-vowel/velar-sibilant/diphthong/coronal hypothesis appears across the relative-position variants. Excite provides a joint interpretation of two similar queries; their distance 3893 is less convincing evidence of repetition. Outfit, iceskate, thinker, outside, and whiskey remain plausible.',
 'cowbell':'The ensemble itself ranks cowbell first for this query. Its nearest possible repeat is substantially farther away (4812), so I do not impose the supine interpretation from that other recording.',
 'cases':'Cases and kisses are close alternatives in both relative-position and shared-gesture models. The /EY/ versus /IH/ vowel and final /S/ versus /Z/ are uncertain. I selected cases as the lexical interpretation, without assigning the addition query the same word.',
 'dismay':'Dismay ranks highly for both recordings and is the leading hypothesis when their ensemble scores are averaged. Their distance 3303 makes a common word plausible. Individual-model alternatives include tennis, aflame, autism, and family. The family result belongs to the weaker fixed-gesture model, not a reliable independent identification.',
 'critic':'Both query recordings have velar-final, front-vowel, coronal/liquid hypotheses. The shared-gesture model ranks critic 5 and 15, providing support beyond the relative-position models, which favor name aliases. Relic, retake, rhetoric, and several unrelated words remain plausible. Their distance is 3346.',
 'supine':'Supine is the ensemble argmax for this recording. The pronunciation with an initial central vowel scores best. Turbine, cowbell, cabbage, and name aliases are alternatives; the distant cowbell recording is not assumed to be the same word.',
 'addition':'Vowel-initial and medial coronal/sibilant patterns support the addition/edition pronunciation family. This is particularly uncertain: audition, dozen, shyness, courteous, and cases remain alternatives. Neural evidence cannot distinguish addition from its homophone edition.'}
for r in review:r['reason']=notes[r['word']]
json.dump(dict(status='Human best guesses, not algorithm argmax or ground truth',word_choices=review,possible_repetition_is_an_inference_not_supplied_metadata=True),open('human_conclusions.json','w'),indent=2)
result=dict(predictions=[dict(id=qid,word=w,phonemes=' '.join(chosenp[w])) for qid,w in zip(ids,choices)],method=dict(summary='Compositional phoneme/articulatory ridge models fitted only to calibration neural activity, tested with whole word types withheld, then searched across all supplied dictionary pronunciations. Final words are my linguistic interpretations of model alternatives and possible repeated recordings.',validation='42 held-out word types: ensemble median pronunciation rank 38.5 across 134860 dictionary pronunciations; 11/42 ranked within the top 10. These are exploratory calibration results, not query accuracy.',evidence=['analysis_report.md','algorithm_only_outputs.json','human_conclusions.json','final_fitted_model.npz','final_validation.json']),limitations=['All predictions have low confidence; exact words are not uniquely determined by these recordings.','Timing, pronunciation variants, uncalibrated phonemes, and presumed query repetitions introduce uncertainty. Homophones cannot be resolved neurally.','Final choices differ from raw algorithm rankings; no query targets, external neural models, network, or delegates were used.'])
json.dump(result,open('final_predictions.json','w'),indent=2)
assert len(result['predictions'])==16 and len(set(ids))==16 and set(ids)==set(x['id'] for x in result['predictions'])
assert not any(w in known for w in choices)
print([(r['id'],r['word'],r['ensemble_pronunciation_rank'],r['gesture_model_pronunciation_rank']) for r in review])
